using System;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;
using ElementalHearts;using Verse;using Verse.AI;using UnityEngine;
class StormBlitzRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Set(object o,string name,object value){o.GetType().GetField(name,F).SetValue(o,value);}
 static object Get(object o,string name){return o.GetType().GetField(name,F).GetValue(o);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(StormBlitzRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  foreach(float dist in new[]{0f,1,2,5,8,12,100}){int duration=StormBlitzRules.Duration(dist);Check(duration>=6&&duration<=14,"Unbounded dash duration");float prior=0;for(int i=0;i<=duration;i++){float progress=StormBlitzRules.Progress(i,duration);Check(progress>=prior&&progress<=1,"Movement progress not monotonic");prior=progress;}Check(prior==1&&StormBlitzRules.Progress(-1,duration)==0,"Movement endpoint/clamping");}
  var start=new IntVec3(10,0,10);var target=new IntVec3(14,0,10);IntVec3 end;
  Func<IntVec3,bool> free=c=>c.x>=0&&c.x<=30&&c.z>=0&&c.z<=30&&c!=target;
  Check(ThunderstormBlitz.ChooseLanding(start,target,8,free,(a,b)=>true,out end)&&end.x>target.x&&end.DistanceToSquared(target)<=2&&start.DistanceToSquared(end)<=64,"Planner fails to prefer a safe through-target landing");
  Check(ThunderstormBlitz.ChooseLanding(start,target,8,c=>free(c)&&c!=new IntVec3(15,0,10),(a,b)=>true,out end)&&end!=new IntVec3(15,0,10),"Occupied preferred landing not rejected");
  Check(!ThunderstormBlitz.ChooseLanding(start,target,8,c=>false,(a,b)=>true,out end)&&!end.IsValid,"All-occupied route should fail");Check(!ThunderstormBlitz.ChooseLanding(start,target,8,free,(a,b)=>false,out end),"Blocked wall path accepted");Check(!ThunderstormBlitz.ChooseLanding(start,target,1,free,(a,b)=>true,out end),"Out-of-range landing accepted");
  foreach(int count in new[]{0,1,2,3,4})foreach(bool primary in new[]{false,true})foreach(bool eligible in new[]{false,true})foreach(bool duplicate in new[]{false,true})Check(StormBlitzRules.CanGraze(count,primary,eligible,duplicate)==(count<3&&!primary&&eligible&&!duplicate),"Grazing target/cap/dedup policy");
  Check(StormBlitzRules.LaneDistanceSquared(5,1,0,0,10,0)==1&&StormBlitzRules.LaneDistanceSquared(5,2,0,0,10,0)==4,"Lane geometry error");
  Console.WriteLine("PASS: bounded dash duration/progress, through-target safe landing preference, occupied/blocked/range rejection, three-secondary cap, primary exclusion and duplicate-hit policy.");
  var pawn=Empty<Pawn>();pawn.jobs=Empty<Pawn_JobTracker>();var job=new Job{def=new JobDef{defName=ThunderstormBlitz.JobName},count=0};job.targetB=new IntVec3(16,0,10);pawn.jobs.curJob=job;
  var driver=new JobDriver_ThunderstormBlitz{pawn=pawn,job=job};Set(pawn.jobs,"curDriver",driver);Set(driver,"start",start);Set(driver,"duration",10);Set(driver,"elapsed",5);Set(driver,"initialized",true);Set(driver,"moving",true);
  Check(driver.VisualAt(0).x==10.5f&&driver.VisualAt(5).x==13.5f&&driver.VisualAt(10).x==16.5f,"Continuous visual position does not follow dash endpoints");Check(ThunderstormBlitz.Busy(pawn)&&ElementalAnimationBridge.Controlled(pawn),"Dash does not gate concurrent skills");driver.impacting=true;Check(!ElementalAnimationBridge.Controlled(pawn),"Finisher cannot enter its own guarded impact");driver.impacting=false;
  var steps=new List<Toil>((IEnumerable<Toil>)typeof(JobDriver_ThunderstormBlitz).GetMethod("MakeNewToils",F).Invoke(driver,null));Check(steps.Count==3&&steps[0].defaultCompleteMode==ToilCompleteMode.Never&&steps[0].handlingFacing&&steps[2].defaultDuration==6,"Dash job does not own movement and recovery");job.count=1;var finisher=new JobDriver_ThunderstormBlitz{pawn=pawn,job=job};var more=new List<Toil>((IEnumerable<Toil>)typeof(JobDriver_ThunderstormBlitz).GetMethod("MakeNewToils",F).Invoke(finisher,null));Check(more.Count==4&&more[1].defaultDuration==18&&more[1].tickAction!=null,"Sovereign warning is missing or not revalidated");
  job.def.defName="Wait_Combat";Check(!ThunderstormBlitz.Busy(pawn)&&!ElementalAnimationBridge.Controlled(pawn),"Busy flag sticks after replacement order");
  Console.WriteLine("PASS: native movement/recovery and finisher warning toils, continuous draw positions, own-impact gating and immediate release when the current job changes.");
  for(int tick=0;tick<180;tick++){int frame=StormBlitzFx.HaloFrame(tick,7);float blend=StormBlitzFx.HaloBlend(tick,7);Check(frame>=0&&frame<6&&blend>=0&&blend<1&&Math.Abs((1-blend)+blend-1)<.00001,"Halo frame/blend out of bounds");}Check(StormBlitzFx.HaloFrame(29,0)==5&&StormBlitzFx.HaloFrame(30,0)==0&&StormBlitzFx.HaloBlend(30,0)==0,"Halo loop seam");
  var fx=new MapComponent_StormBlitzFX(null);var eType=typeof(MapComponent_StormBlitzFX).GetNestedType("Effect",BindingFlags.NonPublic);var sample=Activator.CreateInstance(eType);eType.GetField("active").SetValue(sample,true);var add=typeof(MapComponent_StormBlitzFX).GetMethod("Add",F);for(int i=0;i<10000;i++)add.Invoke(fx,new[]{sample});Check(((Array)Get(fx,"effects")).Length==128&&((Array)Get(fx,"echoes")).Length==64&&(int)Get(fx,"effectCursor")==10000%128,"Effect stress test grows buffers or breaks ring cursor");
  Console.WriteLine("PASS: six-frame halo loop/crossfade bounds and 10,000 effect insertions retain fixed 128-streak/64-afterimage pools.");
  Set(driver,"committed",true);Set(driver,"struck",new HashSet<int>{101,102});var payload=new StormBlitzSaveCase{driver=driver};string file=Path.Combine(Path.GetTempPath(),"StormBlitz_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"StormBlitzTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectSingleNode("StormBlitzTest/state/driver/EH_blitzElapsed").InnerText=="5"&&xml.SelectSingleNode("StormBlitzTest/state/driver/EH_blitzDuration").InnerText=="10"&&xml.SelectSingleNode("StormBlitzTest/state/driver/EH_blitzCommitted").InnerText=="True"&&xml.SelectNodes("StormBlitzTest/state/driver/EH_blitzStruck/li").Count==2,"Native save loses dash progress, committed hit or dedup IDs");File.Delete(file);
  Console.WriteLine("PASS: native Scribe save output includes progress, duration, initialized/moving state, committed hit and struck IDs. Native loading/GPU rendering remain untested.");
 }
}
public class StormBlitzSaveCase:IExposable {public JobDriver_ThunderstormBlitz driver;public void ExposeData(){Scribe_Deep.Look(ref driver,"driver");}}
